<script setup>defineProps({sources:{type:Array,default:()=>[]}})</script>
<template><div v-if="sources.length" class="sources"><strong>参考来源</strong><div v-for="(source,index) in sources" :key="source.url||`${source.documentId}-${source.pageNumber}-${index}`" class="source" :class="source.type?.toLowerCase()"><span class="source-kind">{{source.type==='WEB'?'网络':'课程资料'}}</span><a v-if="source.type==='WEB'" :href="source.url" target="_blank" rel="noopener noreferrer">{{source.title||source.sourceName}}</a><span v-else>{{source.filename}}</span><small v-if="source.type==='LOCAL'&&source.pageNumber">· 第 {{source.pageNumber}} 页</small><small v-if="source.type==='WEB'&&source.sourceName">· {{source.sourceName}}</small></div></div></template>
